package com.library.model;
import com.library.enums.Role;
import java.time.LocalDate;
public class Member extends User { private long memberId; private String phone,course,department; private int semester; private LocalDate registrationDate; public Member(long id,String n,String e,String p,String s,long memberId,String phone,String course,String department,int semester,LocalDate date){super(id,n,e,p,s,Role.MEMBER);this.memberId=memberId;this.phone=phone;this.course=course;this.department=department;this.semester=semester;this.registrationDate=date;} public long getMemberId(){return memberId;} public void setMemberId(long v){memberId=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getCourse(){return course;} public void setCourse(String v){course=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public int getSemester(){return semester;} public void setSemester(int v){semester=v;} public LocalDate getRegistrationDate(){return registrationDate;} public void setRegistrationDate(LocalDate v){registrationDate=v;} @Override public String getDashboardName(){return "Member Dashboard";} @Override public String toString(){return memberId+" - "+getName();} }
